use crate::*;
#[derive(Clone,Serialize,Debug)]#[serde(rename_all="camelCase")]pub struct Member{pub id:String,pub wall_id:String,pub opening_id:Option<String>,pub role:String,pub material:String,pub group:String,pub x1:f64,pub y1:f64,pub z1:f64,pub x2:f64,pub y2:f64,pub z2:f64,pub width:f64,pub depth:f64,pub length:f64,pub stock_length:f64}
pub fn stud(m:&Member)->bool{["Common","King","Jack","Cripple","Corner backing","Intersection backing","Gable"].contains(&m.role.as_str())}
fn pt(w:&Wall,at:f64,y:f64)->[f64;3]{[w.x+if w.axis=="x"{at}else{0.},y,w.z+if w.axis=="z"{at}else{0.}]}
struct B{ms:Vec<Member>,ids:BTreeMap<String,usize>,wood:String}
impl B{fn add(&mut self,w:&Wall,role:&str,a:[f64;3],b:[f64;3],width:f64,depth:f64,mat:&str,op:Option<&str>){let len=((b[0]-a[0]).powi(2)+(b[1]-a[1]).powi(2)+(b[2]-a[2]).powi(2)).sqrt();if len<0.015{return}let num=self.ids.entry(w.id.clone()).or_default();*num+=1;let stock=[8.,10.,12.,16.,20.].into_iter().find(|s|*s+1e-6>=len).unwrap_or((len/2.).ceil()*2.);self.ms.push(Member{id:format!("{}-F{}",w.id,num),wall_id:w.id.clone(),opening_id:op.map(str::to_string),role:role.into(),material:mat.into(),group:if w.exterior{"Exterior framing"}else{"Interior framing"}.into(),x1:a[0],y1:a[1],z1:a[2],x2:b[0],y2:b[1],z2:b[2],width,depth,length:len,stock_length:stock});}
fn stud(&mut self,w:&Wall,at:f64,bottom:f64,len:f64,role:&str,op:Option<&str>){if len<0.015{return}let wood=self.wood.clone();self.add(w,role,pt(w,at,bottom),pt(w,at,bottom+len),if w.axis=="x"{0.125}else{5.5/12.},if w.axis=="x"{5.5/12.}else{0.125},&wood,op);}
fn horiz(&mut self,w:&Wall,role:&str,start:f64,end:f64,y:f64,dep:f64,mat:&str,op:Option<&str>,side:f64,offset:bool){let mut at=start;let mut first=true;while at<end-0.001{let next=end.min(at+if offset&&first{8.}else{16.});let mut a=pt(w,at,y);let mut b=pt(w,next,y);let ax=if w.axis=="x"{2}else{0};a[ax]+=side;b[ax]+=side;self.add(w,role,a,b,if ["2x8","2x10","2x12"].contains(&mat){0.125}else{5.5/12.},dep,mat,op);at=next;first=false;}}}
pub fn build(ws:&[Wall],c:&Config)->Vec<Member>{let h=c.wall_height;let thick=5.5/12.;let mut b=B{ms:vec![],ids:BTreeMap::new(),wood:if c.stud_type=="LSL studs"{"LSL 2x6"}else{"2x6"}.into()};
for w in ws{let mut os=w.openings.clone();os.sort_by(|a,b|a.at.total_cmp(&b.at));let off=if w.exterior&&w.axis=="z"{thick/2.+0.0625}else{0.0625};let mut grid=vec![off];let mut at=2.;while at<w.length-off{grid.push(at);at+=2.;}if w.length>off*2.{grid.push(w.length-off)}for at in grid{if let Some(o)=os.iter().find(|o|at>o.at-0.3125&&at<o.at+o.width+0.3125){if at>o.at+0.125&&at<o.at+o.width-0.125{let(hd,_)=header(w,o,c);b.stud(w,at,o.bottom+o.height+hd,h-0.25-o.bottom-o.height-hd,"Cripple",Some(&o.id));if o.kind=="window"{b.stud(w,at,0.125,o.bottom-0.25,"Cripple",Some(&o.id));}}}else{b.stud(w,at,0.125,h-0.375,"Common",None)}}for o in &os{let(hd,mat)=header(w,o,c);let bearing=structural::bearing(c,w);
 for side in [-1.,1.]{b.stud(w,if side<0.{o.at-0.1875}else{o.at+o.width+0.1875},0.125,h-0.375,"King",Some(&o.id));if bearing{b.stud(w,if side<0.{o.at-0.0625}else{o.at+o.width+0.0625},0.125,o.bottom+o.height-0.125,"Jack",Some(&o.id));b.horiz(w,"Header ply",o.at-0.125,o.at+o.width+0.125,o.bottom+o.height+hd/2.,hd,mat,Some(&o.id),side*1.75/12.,false);}}
 if !bearing{b.horiz(w,"Flat door header",o.at-0.125,o.at+o.width+0.125,o.bottom+o.height+hd/2.,hd,"2x6",Some(&o.id),0.,false);}
 if o.kind=="window"{b.horiz(w,"Rough sill",o.at,o.at+o.width,o.bottom-0.0625,0.125,"2x6",Some(&o.id),0.,false)}}let mut cursor=0.;for o in os.iter().filter(|o|o.kind!="window"){b.horiz(w,"Bottom plate",cursor,o.at,0.0625,0.125,"2x6",None,0.,false);cursor=o.at+o.width;}b.horiz(w,"Bottom plate",cursor,w.length,0.0625,0.125,"2x6",None,0.,false);b.horiz(w,"Lower top plate",0.,w.length,h-0.1875,0.125,"2x6",None,0.,false);b.horiz(w,"Upper top plate",0.,w.length,h-0.0625,0.125,"2x6",None,0.,true);}
for w in ws.iter().filter(|w|w.exterior&&w.axis=="x"){for at in [0.1875,w.length-0.1875]{let global=w.x+at;if global<0.25||global>c.width-0.25{b.stud(w,at,0.125,h-0.375,"Corner backing",None)}}}for w in ws.iter().filter(|w|!w.exterior){for at in [0.,w.length]{let p=pt(w,at,0.);if ws.iter().any(|o|o.id!=w.id&&o.axis!=w.axis&&if o.axis=="x"{near(p[2],o.z)&&p[0]>=o.x-0.001&&p[0]<=o.x+o.length+0.001}else{near(p[0],o.x)&&p[2]>=o.z-0.001&&p[2]<=o.z+o.length+0.001}){b.stud(w,if at==0.{0.1875}else{w.length-0.1875},0.125,h-0.375,"Intersection backing",None)}}}
for w in ws.iter().filter(|w|w.exterior){let profile=roof::wall_profile(c,w);let mut at=2.;while at<w.length{let p=pt(w,at,0.);let total=if !top_floor(c){0.}else{roof::height(c,p[0],p[2]).max(0.)};let mut bottom=0.;while bottom<total-0.125{let len=(total-0.125-bottom).min(8.);b.stud(w,at,h+bottom,len,"Gable",None);bottom+=len;if bottom<total-0.125{b.horiz(w,"Gable tier blocking",(at-1.).max(0.),(at+1.).min(w.length),h+bottom,0.125,"2x6",None,0.,false);bottom+=0.125;}}at+=2.;}for p in profile.windows(2){if p[0][1].max(p[1][1])<0.01{continue}let a=pt(w,p[0][0],h+p[0][1]-0.0625);let z=pt(w,p[1][0],h+p[1][1]-0.0625);let len=((z[0]-a[0]).powi(2)+(z[1]-a[1]).powi(2)+(z[2]-a[2]).powi(2)).sqrt();let pieces=(len/16.).ceil()as usize;for i in 0..pieces{let t=i as f64/pieces as f64;let u=(i+1)as f64/pieces as f64;let interp=|t:f64|[a[0]+(z[0]-a[0])*t,a[1]+(z[1]-a[1])*t,a[2]+(z[2]-a[2])*t];b.add(w,"Gable rake plate",interp(t),interp(u),thick,0.125,"2x6",None);}}
}b.ms}
pub fn cavity(ws:&[Wall],ms:&[Member],h:f64)->f64{let mut total=0.;for w in ws.iter().filter(|w|w.exterior){let mut rects=vec![];for m in ms.iter().filter(|m|m.wall_id==w.id&&m.y1<h&&m.y2<=h){let a=if w.axis=="x"{m.x1-w.x}else{m.z1-w.z};let b=if w.axis=="x"{m.x2-w.x}else{m.z2-w.z};rects.push(if near(a,b){[(a-0.0625).max(0.),(b+0.0625).min(w.length),m.y1.min(m.y2).max(0.),m.y1.max(m.y2).min(h)]}else{[a.min(b).max(0.),a.max(b).min(w.length),(m.y1-m.depth/2.).max(0.),(m.y1+m.depth/2.).min(h)]});}for o in &w.openings{rects.push([o.at,o.at+o.width,o.bottom,o.bottom+o.height]);}rects.retain(|r|r[1]>r[0]&&r[3]>r[2]);let mut xs=vec![0.,w.length];for r in &rects{xs.extend([r[0],r[1]]);}xs.sort_by(f64::total_cmp);xs.dedup_by(|a,b|near(*a,*b));let mut cover=0.;for p in xs.windows(2){let x=(p[0]+p[1])/2.;let mut ys:Vec<_>=rects.iter().filter(|r|x>r[0]&&x<r[1]).map(|r|(r[2],r[3])).collect();ys.sort_by(|a,b|a.0.total_cmp(&b.0));let mut last=0.;let mut ht=0.;for(a,b)in ys{if b>last{ht+=b-a.max(last);last=b;}}cover+=(p[1]-p[0])*ht;}total+=w.length*h-cover;}total.max(0.)}

/// Dimensional estimating candidates; site loads and the adopted header table must be verified.
pub fn header(w:&Wall,o:&Opening,c:&Config)->(f64,&'static str){if !structural::bearing(c,w){(0.125,"2x6")}else if o.width>4.&&(o.bottom+o.height+11.25/12.)<=c.wall_height-0.25{(11.25/12.,"2x12")}else{(9.25/12.,"2x10")}}

pub fn add_backing(ms:&mut Vec<Member>,ws:&[Wall],c:&Config,fs:&[staging::Furniture]){
 let mut seen=std::collections::BTreeSet::new();
 for f in fs{
  let rows:Vec<f64>=match f.kind.as_str(){"kitchen"|"counter-run"|"pantry-cabinet"|"pantry-tower"=>vec![2.8,4.5,6.8],"shower"|"toilet"=>vec![2.8,3.5],"vanity"|"double-vanity"=>vec![2.8],"console"=>vec![3.5,5.],"wallbed"=>vec![c.wall_height-0.5],_=>continue};
  let direction=(f.rotation/std::f64::consts::FRAC_PI_2).round()as i32;
  if (f.rotation-direction as f64*std::f64::consts::FRAC_PI_2).abs()>0.05{continue}
  let along=direction.rem_euclid(2)==0;
  let line=match direction.rem_euclid(4){0=>f.z-f.local_depth/2.,1=>f.x+f.local_depth/2.,2=>f.z+f.local_depth/2.,_=>f.x-f.local_depth/2.};
  let center=if along{f.x}else{f.z};
  let wall=ws.iter().filter(|w|(w.axis=="x")==along&&(if along{w.z}else{w.x}-line).abs()<0.7).min_by(|a,b|(if along{a.z}else{a.x}-line).abs().total_cmp(&(if along{b.z}else{b.x}-line).abs()));
  let Some(wall)=wall else{continue};let origin=if along{wall.x}else{wall.z};
  let lo=(center-f.local_width/2.-origin).max(0.);let hi=(center+f.local_width/2.-origin).min(wall.length);
  for y in rows.into_iter().filter(|y|*y<c.wall_height-0.4){let mut at=(lo/2.).floor()*2.;while at<hi{let end=(at+2.).min(wall.length);let a=at+0.0625;let b=end-0.0625;
   if b>a&&wall.openings.iter().all(|o|b<=o.at||a>=o.at+o.width||y+5.5/24.<=o.bottom||y-5.5/24.>=o.bottom+o.height){let key=format!("{}-{:.3}-{:.3}",wall.id,at,y);if seen.insert(key.clone()){let p=pt(wall,a,y);let q=pt(wall,b,y);ms.push(Member{id:format!("{}-BLOCK-{}",wall.id,seen.len()),wall_id:wall.id.clone(),opening_id:None,role:"Cabinet / fixture backing".into(),material:"2x6".into(),group:if wall.exterior{"Exterior framing"}else{"Interior framing"}.into(),x1:p[0],y1:p[1],z1:p[2],x2:q[0],y2:q[1],z2:q[2],width:0.125,depth:5.5/12.,length:b-a,stock_length:8.});}}
   at+=2.;
  }}
 }
}
